-- =====================================================================
-- Cruise Ops: CLOUD schema (PostgreSQL 15+)
--
-- Conventions:
--   * id: UUID v7 generated by the application (default gen_random_uuid() is only a fallback)
--   * Every table synced down to the hub has: ship_id (or derivable), version, deleted_at
--   * Soft delete only (deleted_at). No physical DELETE on synced tables
--   * The capture_change() trigger writes change_log and allocates a per-ship seq
--     in the SAME transaction as the data (the ship_seq row lock is held until commit,
--     so seq order matches commit order and the hub never misses a row)
--   * Statuses use text + CHECK: easy to migrate and consistent with SQLite on the hub
--   * Sensitive data (passport, emergency contact) is encrypted at the application layer
--     (envelope encryption with KMS) and stored as bytea
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS btree_gist;   -- exclusion constraints on uuid/int

-- ---------------------------------------------------------------------
-- 1. TENANT, ADMIN USERS, GUEST ACCOUNTS
-- ---------------------------------------------------------------------
CREATE TABLE tenants (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);

CREATE TABLE admin_users (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  account_id    uuid,
  email         text NOT NULL,
  display_name  text NOT NULL,
  idp_subject   text,                         -- sub from the company's OIDC SSO (if any)
  role          text NOT NULL CHECK (role IN
                  ('super_admin','fleet_manager','ship_admin','supervisor','partner_admin','analyst')),
  mfa_enabled   boolean NOT NULL DEFAULT false,
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),
  last_login_at timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz
);
CREATE UNIQUE INDEX uq_admin_users_email ON admin_users (lower(email)) WHERE deleted_at IS NULL;

-- Ship scope of each admin user (RBAC + scope)
CREATE TABLE admin_ship_access (
  admin_user_id uuid NOT NULL REFERENCES admin_users(id),
  ship_id       uuid NOT NULL,                -- FK added after the ships table exists
  PRIMARY KEY (admin_user_id, ship_id)
);

CREATE TABLE accounts (                         -- guest account (OAuth)
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email         text,
  display_name  text,
  phone         text,
  locale        text NOT NULL DEFAULT 'en',
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz
);
CREATE UNIQUE INDEX uq_accounts_email ON accounts (lower(email)) WHERE email IS NOT NULL AND deleted_at IS NULL;

ALTER TABLE admin_users
  ADD CONSTRAINT admin_users_account_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id);
CREATE UNIQUE INDEX uq_admin_users_account ON admin_users (account_id)
  WHERE account_id IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE account_identities (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id    uuid NOT NULL REFERENCES accounts(id),
  provider      text NOT NULL CHECK (provider IN ('google','apple','email_otp','firebase')),
  provider_sub  text NOT NULL,
  email         text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, provider_sub)
);
CREATE INDEX ix_account_identities_account ON account_identities (account_id);

-- Rotating refresh tokens; only the hash is stored. Reuse of an old token => revoke the whole family.
CREATE TABLE refresh_tokens (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subject_type  text NOT NULL CHECK (subject_type IN ('account','admin')),
  subject_id    uuid NOT NULL,
  family_id     uuid NOT NULL,
  client        text NOT NULL DEFAULT 'guest_mobile' CHECK (client IN ('guest_mobile','fleet_console')),
  token_hash    bytea NOT NULL UNIQUE,
  issued_at     timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL,
  used_at       timestamptz,
  revoked_at    timestamptz,
  replaced_by   uuid,
  user_agent    text
);
CREATE INDEX ix_refresh_tokens_family  ON refresh_tokens (family_id);
CREATE INDEX ix_refresh_tokens_subject ON refresh_tokens (subject_type, subject_id);

-- ---------------------------------------------------------------------
-- 2. SHIPS, DECKS, ROOMS, AREAS
-- ---------------------------------------------------------------------
CREATE TABLE ships (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES tenants(id),
  name        text NOT NULL,
  imo_number  text UNIQUE,
  flag_state  text,
  timezone    text NOT NULL DEFAULT 'UTC',
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','maintenance','retired')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
ALTER TABLE admin_ship_access ADD FOREIGN KEY (ship_id) REFERENCES ships(id);

CREATE TABLE decks (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id     uuid NOT NULL REFERENCES ships(id),
  level       int  NOT NULL,
  name        text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE UNIQUE INDEX uq_decks_level ON decks (ship_id, level) WHERE deleted_at IS NULL;

CREATE TABLE areas (                            -- common areas: restaurant, lobby, open deck, stairwell...
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id     uuid NOT NULL REFERENCES ships(id),
  deck_id     uuid NOT NULL REFERENCES decks(id),
  name        text NOT NULL,
  area_type   text NOT NULL CHECK (area_type IN
                ('restaurant','lobby','open_deck','theatre','shop','corridor','stairwell','spa','pool','other')),
  capacity    int,
  layout      jsonb,                              -- coordinates on the deck map
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE INDEX ix_areas_ship_deck ON areas (ship_id, deck_id);

CREATE TABLE rooms (                            -- master data only; room status lives on the hub (room_states)
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id     uuid NOT NULL REFERENCES ships(id),
  deck_id     uuid NOT NULL REFERENCES decks(id),
  number      text NOT NULL,
  room_type   text NOT NULL CHECK (room_type IN ('inside','oceanview','balcony','suite','crew','other')),
  capacity    smallint NOT NULL CHECK (capacity > 0),
  is_bookable boolean NOT NULL DEFAULT true,
  layout      jsonb,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE UNIQUE INDEX uq_rooms_number ON rooms (ship_id, number) WHERE deleted_at IS NULL;
CREATE INDEX ix_rooms_deck ON rooms (deck_id);

CREATE TABLE ship_structure_imports (           -- cloud-only import orchestration; never synced
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id           uuid NOT NULL REFERENCES ships(id),
  idempotency_key   text,
  status            text NOT NULL DEFAULT 'validating'
                      CHECK (status IN ('uploaded','validating','ready','failed','processing','completed')),
  file_name         text NOT NULL,
  file_size_bytes   bigint NOT NULL CHECK (file_size_bytes >= 0),
  file_sha256       text NOT NULL CHECK (file_sha256 ~ '^[0-9a-f]{64}$'),
  decks_total       integer NOT NULL DEFAULT 0 CHECK (decks_total >= 0),
  decks_valid       integer NOT NULL DEFAULT 0 CHECK (decks_valid >= 0),
  decks_invalid     integer NOT NULL DEFAULT 0 CHECK (decks_invalid >= 0),
  areas_total       integer NOT NULL DEFAULT 0 CHECK (areas_total >= 0),
  areas_valid       integer NOT NULL DEFAULT 0 CHECK (areas_valid >= 0),
  areas_invalid     integer NOT NULL DEFAULT 0 CHECK (areas_invalid >= 0),
  rooms_total       integer NOT NULL DEFAULT 0 CHECK (rooms_total >= 0),
  rooms_valid       integer NOT NULL DEFAULT 0 CHECK (rooms_valid >= 0),
  rooms_invalid     integer NOT NULL DEFAULT 0 CHECK (rooms_invalid >= 0),
  validated_payload jsonb,
  validation_errors jsonb NOT NULL DEFAULT '[]'::jsonb,
  error_message     text,
  created_by        text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  completed_at      timestamptz,
  CHECK (decks_valid + decks_invalid = decks_total),
  CHECK (areas_valid + areas_invalid = areas_total),
  CHECK (rooms_valid + rooms_invalid = rooms_total)
);
CREATE UNIQUE INDEX uq_ship_structure_imports_idem
  ON ship_structure_imports (ship_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;
CREATE INDEX ix_ship_structure_imports_ship_created
  ON ship_structure_imports (ship_id, created_at DESC);

-- ---------------------------------------------------------------------
-- 3. PORTS, VOYAGES, ITINERARY
-- ---------------------------------------------------------------------
CREATE TABLE ports (                            -- shared reference data, sent down to every ship
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  un_locode    text NOT NULL UNIQUE,
  name         text NOT NULL,
  country_code char(2) NOT NULL,
  latitude     numeric(9,6),
  longitude    numeric(9,6),
  timezone     text NOT NULL DEFAULT 'UTC',
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  version      bigint NOT NULL DEFAULT 1,
  deleted_at   timestamptz
);

CREATE TABLE voyages (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id           uuid NOT NULL REFERENCES ships(id),
  code              text NOT NULL,
  status            text NOT NULL DEFAULT 'planned' CHECK (status IN
                      ('planned','prepared','boarding','sailing','completed','cancelled')),
  departure_at      timestamptz NOT NULL,          -- departure time; the scheduler recomputes when it changes
  arrival_at        timestamptz NOT NULL,
  boarding_opens_at timestamptz,
  manifest_frozen_at timestamptz,
  ownership         text NOT NULL DEFAULT 'cloud' CHECK (ownership IN ('cloud','ship')),
  schedule_version  int  NOT NULL DEFAULT 1,       -- bumped when the time changes => stale jobs are skipped
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           bigint NOT NULL DEFAULT 1,
  deleted_at        timestamptz,
  CHECK (arrival_at > departure_at),
  UNIQUE (ship_id, code),
  -- a ship cannot run two voyages that overlap in time
  CONSTRAINT ex_voyages_no_overlap EXCLUDE USING gist
    (ship_id WITH =, tstzrange(departure_at, arrival_at) WITH &&)
    WHERE (status <> 'cancelled' AND deleted_at IS NULL)
);
CREATE INDEX ix_voyages_departure ON voyages (departure_at) WHERE status IN ('planned','prepared','boarding');

CREATE TABLE port_calls (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id           uuid NOT NULL REFERENCES ships(id),
  voyage_id         uuid NOT NULL REFERENCES voyages(id),
  port_id           uuid NOT NULL REFERENCES ports(id),
  sequence          int  NOT NULL CHECK (sequence >= 1),
  eta               timestamptz,
  etd               timestamptz,
  ata               timestamptz,
  atd               timestamptz,
  allows_embark     boolean NOT NULL DEFAULT true,
  allows_disembark  boolean NOT NULL DEFAULT true,
  status            text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','arrived','departed','skipped')),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           bigint NOT NULL DEFAULT 1,
  deleted_at        timestamptz
);
CREATE UNIQUE INDEX uq_port_calls_seq ON port_calls (voyage_id, sequence) WHERE deleted_at IS NULL;

-- ---------------------------------------------------------------------
-- 4. STAFF, SHIFT TEMPLATES, RULES, AI PARAMETERS
-- ---------------------------------------------------------------------
CREATE TABLE staff (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES tenants(id),
  ship_id        uuid REFERENCES ships(id),        -- ship the person is currently assigned to
  employee_code  text NOT NULL,
  full_name      text NOT NULL,
  department     text NOT NULL CHECK (department IN ('security','cleaning','operator')),
  role_title     text,
  is_supervisor  boolean NOT NULL DEFAULT false,
  languages      text[] NOT NULL DEFAULT '{}',
  phone          text,
  certifications jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(certifications) = 'array'),
                                                   -- [{code, expires_on}] for the rule engine
  status         text NOT NULL DEFAULT 'active' CHECK (status IN ('active','on_leave','sick','inactive')),
  hired_on       date,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  version        bigint NOT NULL DEFAULT 1,
  deleted_at     timestamptz
);
CREATE UNIQUE INDEX uq_staff_code ON staff (tenant_id, employee_code) WHERE deleted_at IS NULL;
CREATE INDEX ix_staff_ship_dept ON staff (ship_id, department);

CREATE TABLE staff_leaves (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  staff_id    uuid NOT NULL REFERENCES staff(id),
  leave_type  text NOT NULL CHECK (leave_type IN ('annual','sick','rest','training','other')),
  starts_at   timestamptz NOT NULL,
  ends_at     timestamptz NOT NULL,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz,
  CHECK (ends_at > starts_at)
);
CREATE INDEX ix_staff_leaves_staff ON staff_leaves (staff_id, starts_at);

CREATE TABLE staff_credentials (                 -- hashed PIN (Argon2id) for offline login on the hub
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  staff_id       uuid NOT NULL UNIQUE REFERENCES staff(id),
  pin_hash       text NOT NULL,
  pin_updated_at timestamptz NOT NULL DEFAULT now(),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  version        bigint NOT NULL DEFAULT 1,
  deleted_at     timestamptz
);

CREATE TABLE shift_templates (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id     uuid NOT NULL REFERENCES ships(id),
  department  text NOT NULL CHECK (department IN ('security','cleaning','operator')),
  code        text NOT NULL,
  name        text NOT NULL,
  start_time  time NOT NULL,
  end_time    time NOT NULL,                       -- end_time < start_time => overnight shift
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE UNIQUE INDEX uq_shift_templates_code ON shift_templates (ship_id, code) WHERE deleted_at IS NULL;

CREATE TABLE coverage_requirements (             -- baseline demand: how many people each shift needs, and where
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id           uuid NOT NULL REFERENCES ships(id),
  department        text NOT NULL CHECK (department IN ('security','cleaning','operator')),
  shift_template_id uuid NOT NULL REFERENCES shift_templates(id),
  position_code     text NOT NULL,
  deck_id           uuid REFERENCES decks(id),
  area_id           uuid REFERENCES areas(id),
  min_staff         smallint NOT NULL CHECK (min_staff >= 0),
  max_staff         smallint CHECK (max_staff IS NULL OR max_staff >= min_staff),
  days_of_week      smallint[] NOT NULL DEFAULT '{1,2,3,4,5,6,7}',
  valid_from        date,
  valid_to          date,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           bigint NOT NULL DEFAULT 1,
  deleted_at        timestamptz
);
CREATE INDEX ix_coverage_ship ON coverage_requirements (ship_id, department);

CREATE TABLE labor_rules (                       -- hard/soft rules for the rule engine; ship_id NULL = tenant-wide
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES tenants(id),
  ship_id     uuid REFERENCES ships(id),
  rule_code   text NOT NULL,                       -- e.g. min_rest_hours, max_weekly_hours
  severity    text NOT NULL CHECK (severity IN ('hard','soft')),
  params      jsonb NOT NULL DEFAULT '{}',
  valid_from  date,
  valid_to    date,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE INDEX ix_labor_rules_scope ON labor_rules (tenant_id, ship_id);

CREATE TABLE autonomy_policies (                 -- AI autonomy level per change type
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES tenants(id),
  ship_id     uuid REFERENCES ships(id),
  change_type text NOT NULL,                       -- e.g. shift_swap, emergency_reassign, security_position
  level       text NOT NULL CHECK (level IN ('auto','conditional','approval','never')),
  conditions  jsonb NOT NULL DEFAULT '{}',         -- e.g. {"max_affected_staff": 3}
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE UNIQUE INDEX uq_autonomy_scope ON autonomy_policies
  (tenant_id, COALESCE(ship_id, '00000000-0000-0000-0000-000000000000'::uuid), change_type)
  WHERE deleted_at IS NULL;

CREATE TABLE ai_params (                         -- versioned, signed parameter/model packages
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  kind          text NOT NULL CHECK (kind IN ('solver_weights','demand_model','intent_schema')),
  param_version int  NOT NULL,
  storage_key   text NOT NULL,                     -- S3 key of the parameter package
  sha256        text NOT NULL,
  kid           text NOT NULL,                     -- signing key id (KMS)
  signature     text NOT NULL,
  status        text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','released','retired')),
  released_at   timestamptz,
  notes         text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  UNIQUE (tenant_id, kind, param_version)
);

-- ---------------------------------------------------------------------
-- 5. BUSINESS PARTNERS
-- ---------------------------------------------------------------------
CREATE TABLE partners (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL REFERENCES tenants(id),
  name          text NOT NULL,
  business_type text NOT NULL CHECK (business_type IN ('entertainment','retail','food_beverage','spa','excursion','other')),
  contact_name  text,
  contact_email text,
  contact_phone text,
  status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended','terminated')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz
);

CREATE TABLE partner_contracts (                 -- which ship a partner operates on, and for how long
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id            uuid NOT NULL REFERENCES ships(id),
  partner_id         uuid NOT NULL REFERENCES partners(id),
  starts_on          date NOT NULL,
  ends_on            date,
  fee_model          text,
  fee_amount_cents   bigint,
  currency           char(3),
  terms_storage_key  text,
  status             text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','expired','terminated')),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  version            bigint NOT NULL DEFAULT 1,
  deleted_at         timestamptz
);
CREATE INDEX ix_partner_contracts_ship ON partner_contracts (ship_id, partner_id);

CREATE TABLE partner_staff (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id     uuid NOT NULL REFERENCES ships(id),
  partner_id  uuid NOT NULL REFERENCES partners(id),
  full_name   text NOT NULL,
  role_title  text,
  phone       text,
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  valid_from  date,
  valid_to    date,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  version     bigint NOT NULL DEFAULT 1,
  deleted_at  timestamptz
);
CREATE INDEX ix_partner_staff_partner ON partner_staff (partner_id, ship_id);

CREATE TABLE partner_services (                  -- services/products guests can book
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id          uuid NOT NULL REFERENCES ships(id),
  partner_id       uuid NOT NULL REFERENCES partners(id),
  area_id          uuid REFERENCES areas(id),
  name             text NOT NULL,
  category         text NOT NULL CHECK (category IN ('entertainment','retail','food_beverage','spa','excursion','other')),
  price_cents      bigint,
  currency         char(3),
  requires_slot    boolean NOT NULL DEFAULT false,
  default_capacity int,
  is_active        boolean NOT NULL DEFAULT true,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  version          bigint NOT NULL DEFAULT 1,
  deleted_at       timestamptz
);
CREATE INDEX ix_partner_services_ship ON partner_services (ship_id, partner_id);

CREATE TABLE partner_slots (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id       uuid NOT NULL REFERENCES ships(id),
  partner_id    uuid NOT NULL REFERENCES partners(id),
  area_id       uuid NOT NULL REFERENCES areas(id),
  voyage_id     uuid REFERENCES voyages(id),
  service_id    uuid REFERENCES partner_services(id),
  start_at      timestamptz NOT NULL,
  end_at        timestamptz NOT NULL,
  capacity      int,
  status        text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','approved','rejected','cancelled')),
  source        text NOT NULL DEFAULT 'cloud' CHECK (source IN ('cloud','ship')),
  requested_by  uuid,
  decided_by    uuid,
  decided_at    timestamptz,
  decision_note text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  CHECK (end_at > start_at),
  -- prevent double-booked slots at the DB layer: the final decision, not dependent on Redis
  CONSTRAINT ex_partner_slots_no_overlap EXCLUDE USING gist
    (area_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&)
    WHERE (status = 'approved' AND deleted_at IS NULL)
);
CREATE INDEX ix_partner_slots_ship_time ON partner_slots (ship_id, start_at);

-- ---------------------------------------------------------------------
-- 6. BOOKINGS, GUESTS, SERVICES
-- ---------------------------------------------------------------------
CREATE TABLE bookings (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id            uuid NOT NULL REFERENCES ships(id),
  voyage_id          uuid NOT NULL REFERENCES voyages(id),
  account_id         uuid REFERENCES accounts(id),
  room_id            uuid REFERENCES rooms(id),
  embark_seq         int NOT NULL DEFAULT 1,       -- port_call sequence where the guest embarks
  disembark_seq      int NOT NULL DEFAULT 1000,    -- port_call sequence where the guest disembarks
  status             text NOT NULL DEFAULT 'pending' CHECK (status IN
                       ('pending','confirmed','checked_in','checked_out','cancelled','expired')),
  expires_at         timestamptz,                  -- hold expiry while payment is in progress (10-15 minutes)
  idempotency_key    text,
  special_requests   text,
  source             text NOT NULL DEFAULT 'cloud' CHECK (source IN ('cloud','ship')),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  version            bigint NOT NULL DEFAULT 1,
  deleted_at         timestamptz,
  CHECK (disembark_seq > embark_seq),
  -- a room cannot have two active bookings overlapping on the same voyage segment
  CONSTRAINT ex_bookings_room_no_overlap EXCLUDE USING gist
    (voyage_id WITH =, room_id WITH =, int4range(embark_seq, disembark_seq) WITH &&)
    WHERE (room_id IS NOT NULL AND deleted_at IS NULL
           AND status IN ('pending','confirmed','checked_in'))
);
CREATE UNIQUE INDEX uq_bookings_idem ON bookings (account_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX ix_bookings_voyage ON bookings (voyage_id, status);
CREATE INDEX ix_bookings_pending_expiry ON bookings (expires_at) WHERE status = 'pending';

CREATE TABLE guests (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id            uuid NOT NULL REFERENCES bookings(id),
  full_name             text NOT NULL,
  date_of_birth         date,
  nationality           char(2),
  document_type         text,
  document_enc          bytea,                      -- passport: field-level encryption
  document_key_id       text,
  emergency_contact_enc bytea,
  special_needs         text,
  is_lead               boolean NOT NULL DEFAULT false,
  muster_station        text,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  version               bigint NOT NULL DEFAULT 1,
  deleted_at            timestamptz
);
CREATE INDEX ix_guests_booking ON guests (booking_id);

CREATE TABLE boarding_passes (                    -- signed boarding pass; only metadata is kept, for revocation
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id  uuid NOT NULL REFERENCES bookings(id),
  guest_id    uuid REFERENCES guests(id),
  jti         uuid NOT NULL UNIQUE,
  issued_at   timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  revoked_at  timestamptz
);

CREATE TABLE service_bookings (                   -- service booked BEFORE the manifest is frozen (cloud-owned)
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id         uuid NOT NULL REFERENCES bookings(id),
  partner_service_id uuid NOT NULL REFERENCES partner_services(id),
  slot_id            uuid REFERENCES partner_slots(id),
  guest_id           uuid REFERENCES guests(id),
  quantity           smallint NOT NULL DEFAULT 1 CHECK (quantity > 0),
  status             text NOT NULL DEFAULT 'pending' CHECK (status IN
                       ('pending','confirmed','rejected','cancelled','completed')),
  source             text NOT NULL DEFAULT 'cloud' CHECK (source IN ('cloud','ship')),
  idempotency_key    text,
  price_cents        bigint,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  version            bigint NOT NULL DEFAULT 1,
  deleted_at         timestamptz
);
CREATE UNIQUE INDEX uq_service_bookings_idem ON service_bookings (booking_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX ix_service_bookings_slot ON service_bookings (slot_id) WHERE slot_id IS NOT NULL;

-- ---------------------------------------------------------------------
-- 7. HUB SYNC
-- ---------------------------------------------------------------------
CREATE TABLE ship_seq (                           -- per-ship sequence counter
  ship_id   uuid PRIMARY KEY REFERENCES ships(id),
  last_seq  bigint NOT NULL DEFAULT 0
);

CREATE TABLE change_log (                         -- change log, cloud -> hub
  ship_id        uuid   NOT NULL REFERENCES ships(id),
  seq            bigint NOT NULL,
  entity         text   NOT NULL,
  entity_id      uuid   NOT NULL,
  op             text   NOT NULL CHECK (op IN ('upsert','delete')),
  version        bigint NOT NULL,
  schema_version int    NOT NULL DEFAULT 1,
  payload        jsonb  NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (ship_id, seq)
);
-- Fast-growing table: consider time-based partitioning and cleanup once every hub has acked.

CREATE TABLE hub_devices (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),   -- = hub_id
  ship_id              uuid NOT NULL REFERENCES ships(id),
  name                 text NOT NULL,
  role                 text NOT NULL DEFAULT 'primary' CHECK (role IN ('primary','standby')),
  epoch                int  NOT NULL DEFAULT 1,     -- bumped when the hardware is replaced => data from the old unit is rejected
  cert_serial          text UNIQUE,
  cert_expires_at      timestamptz,
  status               text NOT NULL DEFAULT 'provisioning' CHECK (status IN
                         ('provisioning','active','retired','revoked')),
  software_version     text,
  last_seen_at         timestamptz,
  last_seq_applied     bigint NOT NULL DEFAULT 0,
  last_acked_local_seq bigint NOT NULL DEFAULT 0,
  sync_lag_seconds     int,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  version              bigint NOT NULL DEFAULT 1,
  deleted_at           timestamptz
);
CREATE UNIQUE INDEX uq_hub_primary ON hub_devices (ship_id) WHERE role = 'primary' AND status = 'active';

CREATE TABLE ship_devices (                       -- registered iPads (device token); the hub verifies offline
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id        uuid NOT NULL REFERENCES ships(id),
  device_name    text NOT NULL,
  device_type    text NOT NULL DEFAULT 'ipad' CHECK (device_type IN ('ipad')),
  token_hash     bytea NOT NULL UNIQUE,
  status         text NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),
  registered_at  timestamptz NOT NULL DEFAULT now(),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  version        bigint NOT NULL DEFAULT 1,
  deleted_at     timestamptz
);

CREATE TABLE revocations (                        -- revocation list sent down to the hub
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id       uuid NOT NULL REFERENCES ships(id),
  subject_type  text NOT NULL CHECK (subject_type IN ('device','staff','boarding_pass','partner_staff')),
  subject_id    text NOT NULL,
  reason        text,
  revoked_at    timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz
);
CREATE INDEX ix_revocations_subject ON revocations (subject_type, subject_id);

CREATE TABLE snapshots (                          -- snapshot packages built and stored on S3
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id        uuid NOT NULL REFERENCES ships(id),
  voyage_id      uuid REFERENCES voyages(id),
  phase          text NOT NULL CHECK (phase IN ('prepare','open_boarding','finalize','manual')),
  seq_base       bigint NOT NULL,
  schema_version int NOT NULL DEFAULT 1,
  storage_key    text NOT NULL,
  sha256         text NOT NULL,
  size_bytes     bigint,
  kid            text NOT NULL,
  signature      text NOT NULL,
  status         text NOT NULL DEFAULT 'building' CHECK (status IN ('building','ready','failed','superseded')),
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_snapshots_ship ON snapshots (ship_id, created_at DESC);

CREATE TABLE job_runs (                           -- prevents scheduled jobs from running twice
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  voyage_id        uuid NOT NULL REFERENCES voyages(id),
  job_type         text NOT NULL CHECK (job_type IN
                     ('prepare_snapshot','open_boarding','finalize_manifest','cutoff_check')),
  schedule_version int  NOT NULL,
  status           text NOT NULL DEFAULT 'running' CHECK (status IN ('running','succeeded','failed','skipped')),
  attempt          int  NOT NULL DEFAULT 1,
  started_at       timestamptz NOT NULL DEFAULT now(),
  finished_at      timestamptz,
  error            text,
  UNIQUE (voyage_id, job_type, schedule_version)
);

-- Operational data pushed up from the hub (outbox -> cloud). Deduplicated by (hub_id, local_seq).
CREATE TABLE ops_events (
  hub_id       uuid   NOT NULL REFERENCES hub_devices(id),
  local_seq    bigint NOT NULL,
  ship_id      uuid   NOT NULL REFERENCES ships(id),
  voyage_id    uuid,
  epoch        int    NOT NULL,
  entity       text   NOT NULL,
  entity_id    text   NOT NULL,
  op           text   NOT NULL CHECK (op IN ('upsert','delete')),
  payload      jsonb  NOT NULL,
  occurred_at  timestamptz NOT NULL,
  received_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (hub_id, local_seq)
);
CREATE INDEX ix_ops_events_entity ON ops_events (ship_id, entity, entity_id, received_at DESC);
-- A "projector" worker reads ops_events and updates reporting tables (tasks, attendance,
-- room_states...) in a later phase; reporting tables are designed separately.

-- ---------------------------------------------------------------------
-- 8. AUDIT AND POST-VOYAGE FEEDBACK
-- ---------------------------------------------------------------------
CREATE TABLE audit_log (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  source      text NOT NULL CHECK (source IN ('cloud','hub')),
  actor_type  text NOT NULL CHECK (actor_type IN ('admin','account','staff','hub','system','ai')),
  actor_id    text,
  action      text NOT NULL,
  entity      text,
  entity_id   text,
  ship_id     uuid,
  voyage_id   uuid,
  details     jsonb
);
CREATE INDEX ix_audit_entity ON audit_log (entity, entity_id);
CREATE INDEX ix_audit_ship_time ON audit_log (ship_id, occurred_at DESC);

CREATE TABLE feedback_responses (                 -- stores anonymized text only
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ship_id          uuid NOT NULL REFERENCES ships(id),
  voyage_id        uuid NOT NULL REFERENCES voyages(id),
  respondent_type  text NOT NULL CHECK (respondent_type IN ('guest','staff')),
  respondent_ref   text,                           -- hashed reference; cannot be traced back to a person
  language         text,
  text_redacted    text NOT NULL,
  submitted_at     timestamptz NOT NULL,
  analyzed_at      timestamptz
);
CREATE INDEX ix_feedback_voyage ON feedback_responses (voyage_id);

CREATE TABLE feedback_insights (                  -- LLM analysis output following a fixed schema
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  response_id   uuid NOT NULL REFERENCES feedback_responses(id),
  ship_id       uuid NOT NULL REFERENCES ships(id),
  voyage_id     uuid NOT NULL REFERENCES voyages(id),
  topic         text NOT NULL,
  area_type     text,
  deck_level    int,
  service_code  text,
  severity      smallint CHECK (severity BETWEEN 1 AND 5),
  sentiment     smallint CHECK (sentiment BETWEEN -2 AND 2),
  model_version text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_feedback_insights_ship ON feedback_insights (ship_id, topic);

-- ---------------------------------------------------------------------
-- 9. TRIGGERS: maintain updated_at/version and write change_log
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION touch_row() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  IF TG_OP = 'UPDATE' THEN
    NEW.version := OLD.version + 1;
  END IF;
  RETURN NEW;
END $$;

-- Parameter TG_ARGV[0] = scope of the change sent down to the hub:
--   self            ships (the ship is the row itself)
--   ship            table has a ship_id column
--   staff           table has staff_id  -> the staff member's ship
--   booking         table has booking_id -> the booking's ship
--   ship_or_tenant  ship_id NULL => send to every ship of the tenant
--   tenant          every ship of the tenant
--   all             every ship (reference data, e.g. ports)
--   partner         ships with an active contract with the partner
CREATE OR REPLACE FUNCTION capture_change() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  scope  text := COALESCE(TG_ARGV[0], 'ship');
  j      jsonb := to_jsonb(NEW);
  v_ships uuid[];
  s      uuid;
  v_seq  bigint;
  v_op   text;
BEGIN
  v_op := CASE WHEN NEW.deleted_at IS NOT NULL THEN 'delete' ELSE 'upsert' END;

  IF scope = 'self' THEN
    v_ships := ARRAY[(j->>'id')::uuid];
  ELSIF scope = 'ship' THEN
    v_ships := ARRAY[(j->>'ship_id')::uuid];
  ELSIF scope = 'staff' THEN
    SELECT ARRAY[st.ship_id] INTO v_ships FROM staff st WHERE st.id = (j->>'staff_id')::uuid AND st.ship_id IS NOT NULL;
  ELSIF scope = 'booking' THEN
    SELECT ARRAY[b.ship_id] INTO v_ships FROM bookings b WHERE b.id = (j->>'booking_id')::uuid;
  ELSIF scope = 'ship_or_tenant' THEN
    IF j->>'ship_id' IS NOT NULL THEN
      v_ships := ARRAY[(j->>'ship_id')::uuid];
    ELSE
      SELECT array_agg(sh.id) INTO v_ships FROM ships sh WHERE sh.tenant_id = (j->>'tenant_id')::uuid AND sh.deleted_at IS NULL;
    END IF;
  ELSIF scope = 'tenant' THEN
    SELECT array_agg(sh.id) INTO v_ships FROM ships sh WHERE sh.tenant_id = (j->>'tenant_id')::uuid AND sh.deleted_at IS NULL;
  ELSIF scope = 'all' THEN
    SELECT array_agg(sh.id) INTO v_ships FROM ships sh WHERE sh.deleted_at IS NULL;
  ELSIF scope = 'partner' THEN
    SELECT array_agg(DISTINCT pc.ship_id) INTO v_ships FROM partner_contracts pc
     WHERE pc.partner_id = (j->>'id')::uuid AND pc.status = 'active' AND pc.deleted_at IS NULL;
  ELSE
    RAISE EXCEPTION 'capture_change: invalid scope: %', scope;
  END IF;

  FOREACH s IN ARRAY COALESCE(v_ships, '{}') LOOP
    -- the upsert holds the row lock until commit => seq order matches commit order
    INSERT INTO ship_seq (ship_id, last_seq) VALUES (s, 1)
    ON CONFLICT (ship_id) DO UPDATE SET last_seq = ship_seq.last_seq + 1
    RETURNING last_seq INTO v_seq;

    INSERT INTO change_log (ship_id, seq, entity, entity_id, op, version, payload)
    VALUES (s, v_seq, TG_TABLE_NAME, (j->>'id')::uuid, v_op, (j->>'version')::bigint, j);
  END LOOP;
  RETURN NULL;
END $$;

-- When a new contract is signed, re-send the partner row to the ships (partners uses scope 'partner')
CREATE OR REPLACE FUNCTION touch_partner_on_contract() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE partners SET updated_at = now() WHERE id = NEW.partner_id;
  RETURN NULL;
END $$;

DO $$
DECLARE t text;
BEGIN
  -- updated_at + version for every table that has these columns
  FOREACH t IN ARRAY ARRAY[
    'tenants','admin_users','accounts','ships','decks','areas','rooms','ports','voyages','port_calls',
    'staff','staff_leaves','staff_credentials','shift_templates','coverage_requirements','labor_rules',
    'autonomy_policies','ai_params','partners','partner_contracts','partner_staff','partner_services',
    'partner_slots','bookings','guests','service_bookings','hub_devices','ship_devices','revocations']
  LOOP
    EXECUTE format('CREATE TRIGGER trg_%1$s_touch BEFORE INSERT OR UPDATE ON %1$I
                    FOR EACH ROW EXECUTE FUNCTION touch_row()', t);
  END LOOP;
END $$;

-- Tables synced down to the hub (with scope)
CREATE TRIGGER trg_ships_capture             AFTER INSERT OR UPDATE ON ships                 FOR EACH ROW EXECUTE FUNCTION capture_change('self');
CREATE TRIGGER trg_decks_capture             AFTER INSERT OR UPDATE ON decks                 FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_areas_capture             AFTER INSERT OR UPDATE ON areas                 FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_rooms_capture             AFTER INSERT OR UPDATE ON rooms                 FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_ports_capture             AFTER INSERT OR UPDATE ON ports                 FOR EACH ROW EXECUTE FUNCTION capture_change('all');
CREATE TRIGGER trg_voyages_capture           AFTER INSERT OR UPDATE ON voyages               FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_port_calls_capture        AFTER INSERT OR UPDATE ON port_calls            FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_staff_capture             AFTER INSERT OR UPDATE ON staff                 FOR EACH ROW WHEN (NEW.ship_id IS NOT NULL) EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_staff_leaves_capture      AFTER INSERT OR UPDATE ON staff_leaves          FOR EACH ROW EXECUTE FUNCTION capture_change('staff');
CREATE TRIGGER trg_staff_credentials_capture AFTER INSERT OR UPDATE ON staff_credentials     FOR EACH ROW EXECUTE FUNCTION capture_change('staff');
CREATE TRIGGER trg_shift_templates_capture   AFTER INSERT OR UPDATE ON shift_templates       FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_coverage_capture          AFTER INSERT OR UPDATE ON coverage_requirements FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_labor_rules_capture       AFTER INSERT OR UPDATE ON labor_rules           FOR EACH ROW EXECUTE FUNCTION capture_change('ship_or_tenant');
CREATE TRIGGER trg_autonomy_capture          AFTER INSERT OR UPDATE ON autonomy_policies     FOR EACH ROW EXECUTE FUNCTION capture_change('ship_or_tenant');
CREATE TRIGGER trg_ai_params_capture         AFTER INSERT OR UPDATE ON ai_params             FOR EACH ROW WHEN (NEW.status = 'released') EXECUTE FUNCTION capture_change('tenant');
CREATE TRIGGER trg_partners_capture          AFTER INSERT OR UPDATE ON partners              FOR EACH ROW EXECUTE FUNCTION capture_change('partner');
CREATE TRIGGER trg_partner_contracts_capture AFTER INSERT OR UPDATE ON partner_contracts     FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_partner_contracts_touch_p AFTER INSERT OR UPDATE ON partner_contracts     FOR EACH ROW EXECUTE FUNCTION touch_partner_on_contract();
CREATE TRIGGER trg_partner_staff_capture     AFTER INSERT OR UPDATE ON partner_staff         FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_partner_services_capture  AFTER INSERT OR UPDATE ON partner_services      FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_partner_slots_capture     AFTER INSERT OR UPDATE ON partner_slots         FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_bookings_capture          AFTER INSERT OR UPDATE ON bookings              FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_guests_capture            AFTER INSERT OR UPDATE ON guests                FOR EACH ROW EXECUTE FUNCTION capture_change('booking');
CREATE TRIGGER trg_service_bookings_capture  AFTER INSERT OR UPDATE ON service_bookings      FOR EACH ROW EXECUTE FUNCTION capture_change('booking');
CREATE TRIGGER trg_ship_devices_capture      AFTER INSERT OR UPDATE ON ship_devices          FOR EACH ROW EXECUTE FUNCTION capture_change('ship');
CREATE TRIGGER trg_revocations_capture       AFTER INSERT OR UPDATE ON revocations           FOR EACH ROW EXECUTE FUNCTION capture_change('ship');

-- ---------------------------------------------------------------------
-- 10. SAMPLE QUERIES FOR THE SYNC API
-- ---------------------------------------------------------------------
-- Hub pulls deltas (receives only its own ship's data):
--   SELECT seq, entity, entity_id, op, version, schema_version, payload
--   FROM change_log WHERE ship_id = $1 AND seq > $2 ORDER BY seq LIMIT $3;
--
-- Cloud receives the hub outbox (deduplicated, effectively exactly-once):
--   INSERT INTO ops_events (hub_id, local_seq, ship_id, voyage_id, epoch, entity,
--                           entity_id, op, payload, occurred_at)
--   VALUES (...) ON CONFLICT (hub_id, local_seq) DO NOTHING;
--   -- reject the batch if epoch < hub_devices.epoch (HTTP 409)
--
-- Release expired holds (worker, every minute):
--   UPDATE bookings SET status = 'expired'
--   WHERE status = 'pending' AND expires_at < now();
--
-- Note: once voyages.ownership = 'ship', the cloud accepts updates to
-- bookings / service_bookings / partner_slots for that voyage only from the hub (ops_events).